import { execFileSync } from "node:child_process";
import { mkdtempDisposableSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import {
  fieldIdentifier,
  type RustBindingItem,
  type RustBindingPairing,
} from "./codex-rust-binding.ts";

export const generatedRustHeader =
  "// @generated by verification/tooling/codex-bindings/generate-codex-bindings.ts.";
const sourceHeader = [
  generatedRustHeader,
  "// Source identities and hashes are recorded in verification/schemas/pins.json.",
  "",
].join("\n");
const maximumLines = 1000;
// Keep room for imports, rustfmt expansion, and additional declarations.
const preferredBodyLines = 850;

export function rustLineCount(source: string): number {
  if (source.length === 0) return 0;
  return source.split("\n").length - Number(source.endsWith("\n"));
}

export function assertRustLineLimit(path: string, source: string): void {
  const lines = rustLineCount(source);
  if (lines > maximumLines) {
    throw new Error(`${path}: generated Rust has ${lines} lines, limit is ${maximumLines}`);
  }
}

interface RustModule {
  readonly name: string;
  readonly items: readonly RustBindingItem[];
}

function orderDeclarations(
  items: readonly RustBindingItem[],
  pairings: readonly RustBindingPairing[],
): readonly RustBindingItem[] {
  const owners = new Map<string, RustBindingItem>();
  for (const item of items) {
    for (const name of item.exports) {
      if (owners.has(name)) throw new Error(`duplicate generated Rust type ${name}`);
      owners.set(name, item);
    }
  }
  // Rust attributes Request::Response to the request's type module even when its impl lives elsewhere.
  const responseByRequest = new Map(pairings.map((pairing) => pairing.references));
  const ordered: RustBindingItem[] = [];
  const completed = new Set<RustBindingItem>();
  const visiting = new Set<RustBindingItem>();
  function visit(item: RustBindingItem): void {
    if (completed.has(item)) return;
    if (visiting.has(item)) throw new Error(`${item.name}: cyclic generated Rust type dependency`);
    visiting.add(item);
    const references = [...item.references];
    for (const name of item.exports) {
      const response = responseByRequest.get(name);
      if (response !== undefined) references.push(response);
    }
    for (const reference of references) {
      const owner = owners.get(reference);
      if (owner === undefined)
        throw new Error(`${item.name}: missing generated Rust type ${reference}`);
      if (owner !== item) visit(owner);
    }
    visiting.delete(item);
    completed.add(item);
    ordered.push(item);
  }
  for (const item of items) visit(item);
  return ordered;
}

function packDeclarations(items: readonly RustBindingItem[]): RustBindingItem[][] {
  const partitions: RustBindingItem[][] = [];
  let partition: RustBindingItem[] = [];
  let bodyLines = 0;
  for (const item of items) {
    const itemLines = rustLineCount(item.source);
    if (partition.length !== 0 && bodyLines + 1 + itemLines > preferredBodyLines) {
      partitions.push(partition);
      partition = [];
      bodyLines = 0;
    }
    bodyLines += (partition.length === 0 ? 0 : 1) + itemLines;
    partition.push(item);
  }
  if (partition.length !== 0) partitions.push(partition);
  return partitions;
}

function declarationModule(items: readonly RustBindingItem[]): RustModule {
  const [first] = items;
  if (first === undefined) throw new Error("empty generated declaration module");
  return { name: fieldIdentifier(first.name), items };
}

function moduleSources(
  modules: readonly RustModule[],
  hasNotifications: boolean,
): ReadonlyMap<string, string> {
  const owners = new Map<string, string>();
  const moduleOrder = new Map<string, number>();
  for (const [index, module] of modules.entries()) {
    if (moduleOrder.has(module.name)) throw new Error(`duplicate Rust module ${module.name}`);
    moduleOrder.set(module.name, index);
    for (const item of module.items) {
      for (const name of item.exports) {
        owners.set(name, module.name);
      }
    }
  }

  const files = new Map<string, string>();
  const index = [
    sourceHeader,
    // Keep the handwritten helpers private while preserving the renderer's super:: paths.
    `use super::{CodexRequest, ${hasNotifications ? "CodexServerNotification, " : ""}OpaqueJson, OpaqueJsonObject, StringAlternative,`,
    "    deserialize_object, deserialize_present, deserialize_required_nullable, json_object_tag, sealed};",
    "",
  ];
  for (const [position, module] of modules.entries()) {
    const imports = new Map<string, string[]>();
    for (const reference of new Set(module.items.flatMap((item) => item.references))) {
      const owner = owners.get(reference);
      const ownerPosition = owner === undefined ? undefined : moduleOrder.get(owner);
      if (owner === undefined || ownerPosition === undefined || ownerPosition > position) {
        throw new Error(`${module.name}: missing or later Rust module for ${reference}`);
      }
      if (owner === module.name) continue;
      const names = imports.get(owner) ?? [];
      names.push(reference);
      imports.set(owner, names);
    }
    const useLines = [...imports].map(([owner, names]) =>
      names.length === 1
        ? `use super::${owner}::${names.join("")};`
        : `use super::${owner}::{${names.join(", ")}};`,
    );
    if (module.items.some((item) => item.needsSerde)) {
      useLines.push("use serde::{Deserialize, Serialize};");
    }
    files.set(
      `${module.name}.rs`,
      [
        sourceHeader,
        ...useLines,
        "",
        module.items.map((item) => item.source).join("\n\n"),
        "",
      ].join("\n"),
    );

    const [first] = module.items;
    const last = module.items.at(-1);
    if (first !== undefined && last !== undefined && first !== last) {
      index.push(`// ${first.name} through ${last.name} in dependency order.`);
    }
    index.push(`mod ${module.name};`);
    if (module.items.some((item) => item.exports.length > 0)) {
      index.push(`pub use ${module.name}::*;`);
    }
    index.push("");
  }
  files.set("mod.rs", index.join("\n"));
  return files;
}

function formatModules(
  files: ReadonlyMap<string, string>,
  repository: string,
): ReadonlyMap<string, string> {
  using scratch = mkdtempDisposableSync(join(tmpdir(), "codex-rustfmt-"));
  const paths = [...files].map(([name, source]) => {
    const path = join(scratch.path, name);
    writeFileSync(path, source);
    return path;
  });
  execFileSync(
    "rustfmt",
    [
      "--edition",
      "2024",
      "--config-path",
      join(repository, "rustfmt.toml"),
      "--config",
      "skip_children=true",
      ...paths,
    ],
    { cwd: repository },
  );
  return new Map(
    [...files.keys()].map((name) => [name, readFileSync(join(scratch.path, name), "utf8")]),
  );
}

export function renderRustModules(
  bindings: {
    declarations: readonly RustBindingItem[];
    pairings: readonly RustBindingPairing[];
    notifications?: readonly RustBindingItem[];
  },
  repository: string,
): ReadonlyMap<string, string> {
  const notificationItems = bindings.notifications ?? [];
  const partitions = [
    ...packDeclarations(orderDeclarations(bindings.declarations, bindings.pairings)).map(
      (items) => ({
        items,
        observation: false,
      }),
    ),
    ...packDeclarations(notificationItems).map((items) => ({ items, observation: true })),
  ];
  const pairings = bindings.pairings.map((item) => ({ name: item.name, items: [item] }));
  for (;;) {
    let observationNumber = 0;
    const declarations = partitions.map(({ items, observation }) => {
      if (!observation) return declarationModule(items);
      observationNumber += 1;
      const name =
        observationNumber === 1 ? "observation_events" : `observation_events_${observationNumber}`;
      return { name, items };
    });
    const files = formatModules(
      moduleSources([...declarations, ...pairings], notificationItems.length !== 0),
      repository,
    );
    const oversized = [...files].find(([, source]) => rustLineCount(source) > maximumLines);
    if (oversized === undefined) return files;

    const [filename, source] = oversized;
    const index = declarations.findIndex((module) => `${module.name}.rs` === filename);
    const partition = partitions[index];
    if (partition === undefined || partition.items.length < 2) {
      throw new Error(
        `${filename}: indivisible generated Rust has ${rustLineCount(source)} lines after rustfmt, limit is ${maximumLines}`,
      );
    }
    const middle = Math.ceil(partition.items.length / 2);
    partitions.splice(
      index,
      1,
      { ...partition, items: partition.items.slice(0, middle) },
      { ...partition, items: partition.items.slice(middle) },
    );
  }
}
